[CmdletBinding()]
param([string]$RepoRoot=(Get-Location).Path)
$ErrorActionPreference='Stop'
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path
if(!(Test-Path -LiteralPath (Join-Path $RepoRoot 'GuideVault.sln'))){throw 'Run from GuideVault repository root.'}
$patch=@'
[{"path":"vision/cover_ocr.py","before":["03315c471db8d296c02069cb35691287452e8d4f31193fa35bec4903e4832d6d","1727386d277dddf342ca5b55129905b4097687901b15bf65f8d631b28f57f436"],"after":"33472a8ed90825cbce4012436d25691534d34e21c8fb4d91809a2a77202c2402","payload":""},{"path":"src/Guidevault.Web/GuidevaultMagazineContentScanner.cs","before":["cfede8ae6d04786578994ac40afa81c7cd562b84e66f195d13e38109d36102be"],"after":"ffb75e1582e9ce51f614d57e9f979acdde197b0c1f5b133ec57af6f016fb72e9","payload":""}]
'@ | ConvertFrom-Json
function HashText([string]$s){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$pending=@()
foreach($p in $patch){
    $path=Join-Path $RepoRoot $p.path
    if(!(Test-Path -LiteralPath $path)){throw "Missing source: $($p.path)"}
    $raw=[IO.File]::ReadAllText($path).Replace("`r`n","`n")
    $hash=HashText $raw
    if($hash -ne $p.after -and $p.before -notcontains $hash){throw "Unexpected source revision: $($p.path). No files changed."}
    $target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p.payload))
    if((HashText $target) -ne $p.after){throw "Payload hash mismatch: $($p.path)"}
    if($hash -ne $p.after){$pending+=@{name=$p.path;path=$path;target=$target}}
}
$dockerPath=Join-Path $RepoRoot 'Dockerfile'
$docker=[IO.File]::ReadAllText($dockerPath).Replace("`r`n","`n")
$copy='COPY vision/cover_ocr.py /opt/guidevault-vision/cover_ocr.py'
$guard='RUN /opt/guidevault-vision/bin/python -m py_compile /opt/guidevault-vision/cover_ocr.py && test "$(/opt/guidevault-vision/bin/python /opt/guidevault-vision/cover_ocr.py --self-test)" = "guidevault-vision-deep-v7.1.1"'
if(([regex]::Matches($docker,'(?m)^'+[regex]::Escape($copy)+'$')).Count -ne 1){throw 'Unexpected Dockerfile COPY instruction. No files changed.'}
if(!$docker.Contains($guard)){$pending+=@{name='Dockerfile';path=$dockerPath;target=$docker.Replace($copy+"`n",$copy+"`n"+$guard+"`n")}}
$backup=Join-Path $RepoRoot ('.guidevault-patch-backups/magazine-scanner-v711-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
foreach($p in $pending){$dest=Join-Path $backup $p.name;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null;Copy-Item -LiteralPath $p.path -Destination $dest}
try{
    foreach($p in $pending){
        $bytes=[IO.File]::ReadAllBytes($p.path);$bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191
        # Keep existing BOM on Dockerfile/C#; Python is UTF-8 without BOM. LF is accepted by Git on Windows.
        if($p.name -eq 'vision/cover_ocr.py'){$bom=$false}
        [IO.File]::WriteAllText($p.path,$p.target,[Text.UTF8Encoding]::new($bom))
        if([IO.File]::ReadAllText($p.path) -cne $p.target){throw "Write verification failed: $($p.name)"}
    }
}catch{foreach($p in $pending){Copy-Item -LiteralPath (Join-Path $backup $p.name) -Destination $p.path -Force};throw}
# Stage ONLY the three repaired project files. Never commit or push automatically.
$paths=@('vision/cover_ocr.py','src/Guidevault.Web/GuidevaultMagazineContentScanner.cs','Dockerfile')
foreach($path in $paths){
    $tracked = & git -C $RepoRoot ls-files -- $path
    if($LASTEXITCODE -ne 0){throw "Git ls-files failed: $path"}
    if($tracked){
        & git -C $RepoRoot update-index --no-assume-unchanged -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear assume-unchanged for $path"}
        & git -C $RepoRoot update-index --no-skip-worktree -- $path
        if($LASTEXITCODE -ne 0){throw "Could not clear index flags for $path"}
    }
    & git -C $RepoRoot add -f -- $path
    if($LASTEXITCODE -ne 0){throw "Git staging failed: $path"}
}
foreach($path in $paths){
    & git -C $RepoRoot grep --cached -q -F 'guidevault-vision-deep-v7.1.1' -- $path
    if($LASTEXITCODE -ne 0){throw "Staged compatibility marker missing: $path"}
}
# Verify the staged Python payload, independent of Git's line-ending conversion.
$staged = & git -C $RepoRoot show ':vision/cover_ocr.py'
if($LASTEXITCODE -ne 0){throw 'Cannot read staged Python source.'}
$stagedText=($staged -join "`n")+"`n"
if((HashText $stagedText) -ne $patch[0].after){throw 'Staged Python source hash differs from expected payload.'}
Write-Host "Backup (if changes made): $backup"
Write-Host 'v7.1.1 source hotfix installed and staged. Review git diff --cached before committing.' -ForegroundColor Green
& git -C $RepoRoot diff --cached --stat
